begin;
set local role postgres;
set local search_path=public,extensions;
select extensions.plan(15);
select extensions.is((select jsonb_array_length(manifest->'competencies') from public.curriculum_import_batches where id='v5.1'),451,'451 explicitly supplied items');
select extensions.is((select count(*) from public.curriculum_import_history where batch_id='v5.1' and action='inserted'),337::bigint,'337 additions without duplicate IDs');
select extensions.is((select count(*) from public.curriculum_import_history where batch_id='v5.1' and action='updated'),23::bigint,'23 revised pediatric drafts');
select extensions.is((select count(*) from public.curriculum_import_history where batch_id='v5.1' and action='superseded'),1::bigint,'one overlapping generic draft archived, not deleted');
select extensions.is((select count(*) from public.competencies where code like 'V5.PED.%' and curriculum_status<>'superseded'),116::bigint,'116 current pediatric proposals');
select extensions.is((select count(*) from public.competencies where code like 'V5.GO.%'),155::bigint,'155 GO proposals');
select extensions.is((select count(*) from public.competencies where code like 'V5.PREV.%'),180::bigint,'180 Preventiva proposals');
select extensions.is((select count(distinct t.area_id) from public.competencies c join public.subthemes s on s.id=c.subtheme_id join public.themes t on t.id=s.theme_id where c.code like 'V5.GO.%'),22::bigint,'22 GO subareas');
select extensions.is((select count(distinct t.area_id) from public.competencies c join public.subthemes s on s.id=c.subtheme_id join public.themes t on t.id=s.theme_id where c.code like 'V5.PREV.%'),20::bigint,'20 Preventiva subareas');
select extensions.ok(exists(select 1 from public.competencies c join public.competencies replacement on replacement.id=c.superseded_by where c.code='V5.PED.03.04' and replacement.code='V5.PED.03.05'),'superseded identity retained with explicit replacement');
create temporary table before_import as select id,curriculum_revision,name from public.competencies;
select extensions.lives_ok($$select public.import_curriculum_v51()$$,'repeat import is safe');
select extensions.is((select count(*) from ((select id,curriculum_revision,name from public.competencies except select * from before_import) union all (select * from before_import except select id,curriculum_revision,name from public.competencies)) differences),0::bigint,'repeat import preserves IDs, revisions and names');
select extensions.is((select count(*) from public.curriculum_import_history where batch_id='v5.1'),361::bigint,'repeat import does not duplicate audit history');
create temporary table before_links as select cs.* from public.competency_specialties cs join public.competencies c on c.id=cs.competency_id where c.code like 'V5.%';
insert into public.specialty_areas(specialty_id,area_id) values('50000000-0000-4000-8000-000000000004','51000000-0000-4000-8000-000000000002') on conflict do nothing;
select extensions.is((select count(*) from public.competency_specialties cs join public.competencies c on c.id=cs.competency_id where c.code like 'V5.%'),(select count(*) from before_links),'area association does not invent cross-specialty mappings for drafts');
select extensions.ok(exists(select 1 from public.competency_specialties where competency_id='54000000-0000-4000-8000-000000000003' and specialty_id='50000000-0000-4000-8000-000000000004'),'legacy area inference is preserved');
select * from extensions.finish();
rollback;
